## Why This Is Asked
Tests DP setup for segment selection with non-adjacency and reconstruction, a common beginner DP pattern with a twist.

## Key Concepts
- DP over index i and blocks t
- Enforce non-adjacency via s-2 reference
- Prefix sums for O(1) subarray sums
- Reconstruction pointers for endpoints
- Time/space trade-offs; possible optimization to O(nk) time and O(n) space per k

## Code Example
```javascript
function maxKSubarraysSum(A, k) {
  const n = A.length;
  const P = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) P[i + 1] = P[i] + A[i];

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const take = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-1));
  dp[0][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 0; t <= k; t++) {
      // skip i
      dp[i][t] = Math.max(dp[i][t], dp[i - 1][t]);
      if (t > 0) {
        for (let s = 1; s <= i; s++) {
          const sum = P[i] - P[s - 1];
          const prev = (s >= 2) ? dp[s - 2][t - 1] : (t - 1 === 0 ? 0 : -Infinity);
          const cand = sum + prev;
          if (cand > dp[i][t]) {
            dp[i][t] = cand;
            take[i][t] = s;
          }
        }
      }
    }
  }
  // reconstruction would trace back using 'take' from (n, bestT)
  return { maxSum: dp[n][0], blocks: [] };
}
```

## Why This Question Is Asked
Tests the ability to extend classic path DP problems with an additional resource constraint, evaluating proficiency in managing 3D DP states, path reconstruction via backtracking, and space optimization.

## Key Concepts
- 3D DP state (i, j, t) tracking exact t boosts used at position (i,j)
- Two transition options: boost or skip the current cell
- Path reconstruction by backtracking through the DP table
- Space optimization: reduce to two rows or maintain a compact parent pointer table

## Code Example
```javascript
function maxPathWithBoosts(grid, k, B) {
  const n = grid.length, m = grid[0].length;
  const NEG = -Infinity;
  const dp = Array.from({ length: n }, () =>
    Array.from({ length: m }, () => new Array(k + 1).fill(NEG))
  );
  dp[0][0][0] = grid[0][0];
  if (k > 0) dp[0][0][1] = grid[0][0] + B;

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < m; j++) {
      for (let t = 0; t <= k; t++) {
        if (i > 0 && dp[i-1][j][t] !== NEG) {
          dp[i][j][t] = Math.max(dp[i][j][t], dp[i-1][j][t] + grid[i][j]);
        }
        if (j > 0 && dp[i][j-1][t] !== NEG) {
          dp[i][j][t] = Math.max(dp[i][j][t], dp[i][j-1][t] + grid[i][j]);
        }
        if (t > 0) {
          if (i > 0 && dp[i-1][j][t-1] !== NEG) {
            dp[i][j][t] = Math.max(dp[i][j][t], dp[i-1][j][t-1] + grid[i][j] + B);
          }
          if (j > 0 && dp[i][j-1][t-1] !== NEG) {
            dp[i][j][t] = Math.max(dp[i][j][t], dp[i][j-1][t-1] + grid[i][j] + B);
          }
        }
      }
    }
  }

  const boosts = [];
  let i = n - 1, j = m - 1, t = k;
  while (i > 0 || j > 0) {
    const fromTop = i > 0 && dp[i][j][t] === dp[i-1][j][t] + grid[i][j];
    const fromLeft = j > 0 && dp[i][j][t] === dp[i][j-1][t] + grid[i][j];
    const boostedFromTop = i > 0 && t > 0 && dp[i][j][t] === dp[i-1][j][t-1] + grid[i][j] + B;
    const boostedFromLeft = j > 0 && t > 0 && dp[i][j][t] === dp[i][j-1][t-1] + grid[i][j] + B;

    if (boostedFromTop || boostedFromLeft) boosts.push([i, j]);
    if (boostedFromTop || (i > 0 && fromTop && !boostedFromTop)) { i--; }
    else if (j > 0) { j--; if (!boostedFromLeft && !fromLeft) t--; }
  }

  return { maxSum: dp[n-1][m-1][k], boosts: boosts.reverse() };
}
```

## Complexity
- **Time:** O(n × m × k)
- **Space:** O(n × m × k) or O(m × k) with row optimization

## Why This Is Asked
Tests DP with subarray composition where each block incurs a fixed cost, a realistic pattern in scheduling/payments. It also checks reconstruction of intervals.

## Key Concepts
- Prefix sums to compute subarray sums fast
- DP over positions and block counts
- Optimization: collapse inner max with a running best value per t
- Backpointer reconstruction for endpoints

## Code Example
```javascript
function maxKSubarraySumMinusC(A, k, c) {
  const n = A.length;
  const pref = Array(n+1).fill(0);
  for (let i=1; i<=n; i++) pref[i] = pref[i-1] + A[i-1];
  const dp = Array.from({length: n+1}, ()=> Array(k+1).fill(-1e15));
  const endAt = Array.from({length: n+1}, ()=> Array(k+1).fill(null));
  dp[0][0] = 0;
  const bestVal = Array(k+1).fill(-1e15);
  const bestIdx = Array(k+1).fill(-1);
  bestVal[1] = 0; bestIdx[1] = 1; // allow start at 1 for first block
  for (let i=1; i<=n; i++) {
    for (let t=1; t<=k; t++) {
      const endVal = pref[i] - c + bestVal[t];
      if (dp[i-1][t] >= endVal) {
        dp[i][t] = dp[i-1][t];
      } else {
        dp[i][t] = endVal;
        endAt[i][t] = {start: bestIdx[t], end: i};
      }
    }
    for (let t=1; t<=k; t++) {
      const cand = dp[i][t-1] - pref[i];
      if (cand > bestVal[t]) { bestVal[t] = cand; bestIdx[t] = i+1; }
    }
  }
  const blocks = [];
  let i = n, t = k;
  while (t > 0 && i > 0) {
    const e = endAt[i][t];
    if (e) { blocks.push([e.start, e.end]); i = e.start - 1; t--; }
    else { i--; }
  }
  blocks.reverse();
  return { value: dp[n][k], blocks };
}
```

